"""Program for task-2e29965a: horizontal stripe transformation"""
from collections import Counter

def transform(grid):
    n_rows, n_cols = len(grid), len(grid[0])

    # Extract colored rows (uniform non-zero rows) in order
    colored = []
    for row in grid:
        if len(set(row)) == 1 and row[0] != 0:
            colored.append(int(row[0]))

    # If 3 unique values, swap first two
    if len(set(colored)) == 3 and len(colored) >= 2:
        colors = [colored[1], colored[0]] + colored[2:]
    else:
        colors = colored

    # Create output grid cycling through colors
    output = []
    cycle_len = max(1, len(colors))
    for r in range(n_rows):
        val = colors[r % cycle_len]
        output.append([val] * n_cols)

    return output

